//! B3 (#39): signed admission for delegated agent requests, reusing the
//! `weave-policy` verifier with the tenant's audience and a registry-derived
//! root (ADR-0007 section 8). Every key is generated by the test.
mod common;
use axum::http::{Method, StatusCode};
use common::*;
use ed25519_dalek::SigningKey;
use serde_json::{json, Value};
use std::collections::BTreeSet;
use weave_policy::{
    body_digest, capability_id, public_key, sign_capability, sign_request, Action, AdmissionProof,
    Capability, Operation, Request, Scope, REQUEST_VERSION, VERSION as CAP_VERSION,
};
use weave_service::ids::{hex, random};

fn key() -> SigningKey {
    SigningKey::from_bytes(&random::<32>())
}

struct World {
    h: Harness,
    root: String,
    alice: String,
    bob: String,
    audience: String,
    revision: String,
    alice_key: SigningKey,
    bot_key: SigningKey,
}

/// alice writes `notes`; her agent `alice-bot` has Write on it. alice binds
/// her key, and the bot's key as its owner.
async fn world() -> World {
    let h = Harness::new();
    let (root, alice, bob) = standard_tenant(&h, "acme").await;
    h.post("/v1/graphs", &root, json!({"graph_id": "notes"}))
        .await;
    h.registry(
        &root,
        json!([{"change": "grant", "graph_id": "notes", "subject": "alice", "permission": "write"}]),
    )
    .await;
    let reply = h
        .registry(
            &alice,
            json!([{"change": "add_agent", "id": "alice-bot", "owner": "alice", "delegation": {
                "scopes": [{"graph_id": "notes", "permission": "write"}],
                "exercise": {"kind": "owner_all"}}}]),
        )
        .await;
    assert_eq!(reply.status, StatusCode::OK, "{}", reply.json);
    let (alice_key, bot_key) = (key(), key());
    let reply = h
        .post(
            "/v1/keys",
            &alice,
            json!({"public_key": public_key(&alice_key)}),
        )
        .await;
    assert_eq!(reply.status, StatusCode::CREATED, "{}", reply.json);
    let reply = h
        .post(
            "/v1/keys",
            &alice,
            json!({"public_key": public_key(&bot_key), "principal": "alice-bot"}),
        )
        .await;
    assert_eq!(reply.status, StatusCode::CREATED, "{}", reply.json);
    h.seed("acme", "root", "notes", vec![node("seed", &[], &[])]);
    let me = h.get("/v1/whoami", &alice).await.json;
    World {
        audience: me["admission_audience"].as_str().unwrap().into(),
        revision: me["admission_policy_revision"].as_str().unwrap().into(),
        h,
        root,
        alice,
        bob,
        alice_key,
        bot_key,
    }
}

fn actions(list: &[Action]) -> BTreeSet<Action> {
    list.iter().copied().collect()
}

impl World {
    fn now(&self) -> i64 {
        self.h.now()
    }
    /// A capability from `issuer` to `subject` over `notes/main`.
    fn capability(
        &self,
        issuer: &SigningKey,
        subject: &SigningKey,
        acts: &[Action],
    ) -> weave_policy::SignedCapability {
        let now = self.now();
        sign_capability(
            Capability {
                version: CAP_VERSION.into(),
                issuer: public_key(issuer),
                subject: public_key(subject),
                audience: self.audience.clone(),
                policy_revision: self.revision.clone(),
                scopes: vec![Scope {
                    graph_id: "notes".into(),
                    branch_id: "main".into(),
                    actions: actions(acts),
                }],
                not_before_ms: now - 1_000,
                expires_at_ms: now + 3_600_000,
                delegations_remaining: 0,
                parent: None,
            },
            issuer,
        )
        .unwrap()
    }
    fn body(
        &self,
        chain: Vec<weave_policy::SignedCapability>,
        signer: &SigningKey,
        action: Action,
        program: &Value,
    ) -> (Value, String) {
        let text = program.to_string();
        let now = self.now();
        let request = Request {
            version: REQUEST_VERSION.into(),
            subject: public_key(signer),
            audience: self.audience.clone(),
            capability_id: capability_id(chain.last().unwrap()).unwrap(),
            nonce: hex(&random::<32>()),
            issued_at_ms: now,
            expires_at_ms: now + 60_000,
            operation: Operation {
                action,
                graph_id: "notes".into(),
                branch_id: "main".into(),
            },
            body_digest: body_digest(text.as_bytes()),
        };
        let proof = AdmissionProof {
            chain,
            request: sign_request(request, signer).unwrap(),
        };
        (json!({"proof": proof, "program": text}), text)
    }
    async fn admit(&self, body: &Value) -> Reply {
        self.h
            .send_raw(
                Method::POST,
                "/v1/admit",
                Some("Weave-Signed".into()),
                Some(serde_json::to_vec(body).unwrap()),
            )
            .await
    }
    async fn write_program(&self, id: &str) -> Value {
        json!({"version": weave_contract::VERSION, "commands": [{"op": "write", "graph_id": "notes",
            "changes": [{"change": "assert", "fact": node(id, &[], &[])}]}]})
    }
}

fn read_program() -> Value {
    json!({"version": weave_contract::VERSION, "commands": [{"op": "query", "query": {"graph_id": "notes"}}]})
}

const ALL: [Action; 4] = [
    Action::Discover,
    Action::Read,
    Action::Traverse,
    Action::Publish,
];

#[tokio::test]
async fn a_signed_agent_request_runs_as_the_agent_under_its_owner() {
    let w = world().await;
    // The agent mints IDs through its own token; the signed write uses one.
    let bot_token =
        w.h.post("/v1/tokens", &w.alice, json!({"principal": "alice-bot"}))
            .await
            .json["token"]
            .as_str()
            .unwrap()
            .to_string();
    let id = w.h.ids(&bot_token, 1).await.remove(0);
    let chain = vec![w.capability(&w.alice_key, &w.bot_key, &ALL)];
    let program = w.write_program(&id).await;
    let (body, _) = w.body(chain.clone(), &w.bot_key, Action::Publish, &program);
    let reply = w.admit(&body).await;
    assert_eq!(reply.status, StatusCode::OK, "{}", reply.json);
    // Provenance: the agent wrote it on behalf of alice.
    let read = w.h.query(&w.alice, "notes").await;
    let provenance = &read.json["results"][0]["result"]["fact_provenance"][0]["provenance"];
    assert_eq!(provenance["writer"], "alice-bot");
    assert_eq!(provenance["on_behalf_of"], json!(["alice"]));
    // The audit entry names the agent, the chain and the capability.
    let accesses = w.h.audit_facts(&w.root, "notes", &id).await;
    let write = accesses.iter().find(|a| a["access"] == "write").unwrap();
    assert_eq!(
        (write["principal"].as_str(), write["operation"].as_str()),
        (Some("alice-bot"), Some("admit"))
    );
    assert_eq!(write["on_behalf_of"], json!(["alice"]));
    let entries = w.h.audit_entries(&w.root).await;
    let admitted = entries
        .iter()
        .rev()
        .find(|e| e["operation"] == "admit")
        .unwrap();
    assert!(admitted["credential"].as_str().unwrap().starts_with("cap:"));
    // The same signed request again is a replay.
    let replay = w.admit(&body).await;
    assert_eq!(
        (replay.status, replay.code()),
        (StatusCode::CONFLICT, "E_REPLAY")
    );
    // A signed read.
    let (body, _) = w.body(chain, &w.bot_key, Action::Read, &read_program());
    let reply = w.admit(&body).await;
    assert_eq!(reply.status, StatusCode::OK, "{}", reply.json);
    assert_eq!(node_ids(&reply), [id, "seed".to_string()]);
    // alice can sign for herself, too.
    let own = vec![w.capability(&w.alice_key, &w.alice_key, &ALL)];
    let (body, _) = w.body(own, &w.alice_key, Action::Read, &read_program());
    assert_eq!(w.admit(&body).await.status, StatusCode::OK);
}

#[tokio::test]
async fn every_failed_signature_check_is_the_uniform_401() {
    let w = world().await;
    let reference = w.h.get("/v1/whoami", "wvs_nope").await;
    let chain = vec![w.capability(&w.alice_key, &w.bot_key, &ALL)];
    let program = w.write_program("r-x").await;
    let mut cases: Vec<(&str, Value)> = Vec::new();
    // The program text was changed after signing.
    let (mut body, _) = w.body(chain.clone(), &w.bot_key, Action::Publish, &program);
    body["program"] = json!(read_program().to_string());
    cases.push(("tampered body", body));
    // The operation does not match the program.
    let (body, _) = w.body(chain.clone(), &w.bot_key, Action::Read, &program);
    cases.push(("operation", body));
    // A leaf key that is not bound.
    let stranger = key();
    let chain_s = vec![w.capability(&w.alice_key, &stranger, &ALL)];
    let (body, _) = w.body(chain_s, &stranger, Action::Publish, &program);
    cases.push(("unbound leaf", body));
    // A root key that is not bound.
    let rogue = key();
    let chain_r = vec![w.capability(&rogue, &w.bot_key, &ALL)];
    let (body, _) = w.body(chain_r, &w.bot_key, Action::Publish, &program);
    cases.push(("unbound root", body));
    // A capability without Publish.
    let narrow = vec![w.capability(&w.alice_key, &w.bot_key, &[Action::Read, Action::Traverse])];
    let (body, _) = w.body(narrow, &w.bot_key, Action::Publish, &program);
    cases.push(("scope", body));
    // Another tenant's audience.
    let beta = w.h.tenant("beta", "root");
    let beta_audience = w.h.get("/v1/whoami", &beta).await.json["admission_audience"]
        .as_str()
        .unwrap()
        .to_string();
    let mut other = World {
        ..world_like(&w, &beta_audience)
    };
    other.audience = beta_audience;
    let chain_b = vec![other.capability(&w.alice_key, &w.bot_key, &ALL)];
    let (body, _) = other.body(chain_b, &w.bot_key, Action::Publish, &program);
    cases.push(("other tenant", body));
    // Bob's key as root of a chain to alice's agent: not its ownership chain.
    let bob_key = key();
    w.h.post(
        "/v1/keys",
        &w.bob,
        json!({"public_key": public_key(&bob_key)}),
    )
    .await;
    let chain_bob = vec![w.capability(&bob_key, &w.bot_key, &ALL)];
    let (body, _) = w.body(chain_bob, &w.bot_key, Action::Publish, &program);
    cases.push(("foreign root", body));
    // Not even JSON, or not a proof.
    cases.push(("not a proof", json!({"proof": {"x": 1}, "program": "{}"})));
    for (name, body) in &cases {
        let reply = w.admit(body).await;
        assert_eq!(
            reply.status,
            StatusCode::UNAUTHORIZED,
            "{name}: {}",
            reply.json
        );
        assert_eq!(reply.bytes, reference.bytes, "{name}");
    }
    // The scheme is accepted on its route only, and the route accepts only it.
    let good = w
        .body(chain.clone(), &w.bot_key, Action::Publish, &program)
        .0;
    let reply =
        w.h.send_raw(
            Method::POST,
            "/v1/execute",
            Some("Weave-Signed".into()),
            Some(serde_json::to_vec(&good).unwrap()),
        )
        .await;
    assert_eq!(reply.bytes, reference.bytes);
    let reply = w.h.post("/v1/admit", &w.alice, good).await;
    assert_eq!(reply.bytes, reference.bytes);
}

/// A copy of the world's identity for building proofs with another audience.
fn world_like(w: &World, audience: &str) -> World {
    World {
        h: Harness::new(),
        root: w.root.clone(),
        alice: w.alice.clone(),
        bob: w.bob.clone(),
        audience: audience.into(),
        revision: w.revision.clone(),
        alice_key: w.alice_key.clone(),
        bot_key: w.bot_key.clone(),
    }
}

#[tokio::test]
async fn revocation_reaches_signed_requests_on_the_next_request() {
    let w = world().await;
    let chain = vec![w.capability(&w.alice_key, &w.bot_key, &ALL)];
    let read = |w: &World| {
        w.body(chain.clone(), &w.bot_key, Action::Read, &read_program())
            .0
    };
    assert_eq!(w.admit(&read(&w)).await.status, StatusCode::OK);
    // The owner suspends the agent.
    w.h.registry(
        &w.alice,
        json!([{"change": "set_status", "id": "alice-bot", "status": "suspended"}]),
    )
    .await;
    assert_eq!(w.admit(&read(&w)).await.status, StatusCode::UNAUTHORIZED);
    w.h.registry(
        &w.alice,
        json!([{"change": "set_status", "id": "alice-bot", "status": "active"}]),
    )
    .await;
    assert_eq!(w.admit(&read(&w)).await.status, StatusCode::OK);
    // The owner loses Read: the derived root no longer covers the chain.
    w.h.registry(
        &w.root,
        json!([{"change": "revoke", "graph_id": "notes", "subject": "alice"}]),
    )
    .await;
    assert_eq!(w.admit(&read(&w)).await.status, StatusCode::UNAUTHORIZED);
    w.h.registry(&w.root, json!([{"change": "grant", "graph_id": "notes", "subject": "alice", "permission": "write"}])).await;
    assert_eq!(w.admit(&read(&w)).await.status, StatusCode::OK);
    // Revoking the agent's key; a revoked key can never be bound again.
    let reply =
        w.h.send(
            Method::DELETE,
            &format!("/v1/keys/{}", public_key(&w.bot_key)),
            Some(&w.alice),
            None,
        )
        .await;
    assert_eq!(reply.status, StatusCode::OK, "{}", reply.json);
    assert_eq!(w.admit(&read(&w)).await.status, StatusCode::UNAUTHORIZED);
    let again =
        w.h.post(
            "/v1/keys",
            &w.alice,
            json!({"public_key": public_key(&w.bot_key), "principal": "alice-bot"}),
        )
        .await;
    assert_eq!(again.code(), "E_CONFLICT");
    // Revoking the owner's root key ends every chain it issued.
    let fresh = key();
    w.h.post(
        "/v1/keys",
        &w.alice,
        json!({"public_key": public_key(&fresh), "principal": "alice-bot"}),
    )
    .await;
    let chain = vec![w.capability(&w.alice_key, &fresh, &ALL)];
    let body = w.body(chain, &fresh, Action::Read, &read_program()).0;
    assert_eq!(w.admit(&body).await.status, StatusCode::OK);
    w.h.send(
        Method::DELETE,
        &format!("/v1/keys/{}", public_key(&w.alice_key)),
        Some(&w.alice),
        None,
    )
    .await;
    let chain = vec![w.capability(&w.alice_key, &fresh, &ALL)];
    let body = w.body(chain, &fresh, Action::Read, &read_program()).0;
    assert_eq!(w.admit(&body).await.status, StatusCode::UNAUTHORIZED);
}

#[tokio::test]
async fn key_bindings_follow_ownership_and_signed_programs_are_one_operation() {
    let w = world().await;
    let stranger = key();
    // bob cannot bind a key for alice's agent, or for alice.
    for principal in ["alice-bot", "alice"] {
        let reply =
            w.h.post(
                "/v1/keys",
                &w.bob,
                json!({"public_key": public_key(&stranger), "principal": principal}),
            )
            .await;
        assert_eq!(reply.code(), "E_FORBIDDEN", "{principal}");
    }
    // Malformed keys are refused.
    let reply =
        w.h.post("/v1/keys", &w.bob, json!({"public_key": "ed25519:zz"}))
            .await;
    assert_eq!(reply.code(), "E_INPUT");
    // bob cannot revoke alice's keys, and cannot tell them from missing ones.
    let theirs =
        w.h.send(
            Method::DELETE,
            &format!("/v1/keys/{}", public_key(&w.alice_key)),
            Some(&w.bob),
            None,
        )
        .await;
    let missing =
        w.h.send(
            Method::DELETE,
            &format!("/v1/keys/{}", public_key(&stranger)),
            Some(&w.bob),
            None,
        )
        .await;
    assert_eq!(theirs.status, StatusCode::NOT_FOUND);
    assert_eq!(theirs.bytes, missing.bytes);
    // Listings: own keys, or every key for an administrator.
    assert_eq!(
        w.h.get("/v1/keys", &w.alice).await.json["keys"]
            .as_array()
            .unwrap()
            .len(),
        1
    );
    assert_eq!(
        w.h.get("/v1/keys", &w.root).await.json["keys"]
            .as_array()
            .unwrap()
            .len(),
        2
    );
    // Mixed reads and writes, or two graphs, are not one operation.
    let chain = vec![w.capability(&w.alice_key, &w.bot_key, &ALL)];
    let mixed = json!({"version": weave_contract::VERSION, "commands": [
        {"op": "query", "query": {"graph_id": "notes"}},
        {"op": "write", "graph_id": "notes", "changes": [{"change": "retract", "target": {"kind": "node", "id": "x"}}]}]});
    let two = json!({"version": weave_contract::VERSION, "commands": [
        {"op": "query", "query": {"graph_id": "notes"}},
        {"op": "query", "query": {"graph_id": "other"}}]});
    let other_branch = json!({"version": weave_contract::VERSION, "commands": [
        {"op": "query", "query": {"graph_id": "notes"}},
        {"op": "query", "query": {"graph_id": "notes", "branch_id": "dev"}}]});
    for program in [mixed, two, other_branch] {
        let body = w.body(chain.clone(), &w.bot_key, Action::Read, &program).0;
        let reply = w.admit(&body).await;
        assert_eq!(reply.code(), "E_UNSUPPORTED", "{}", reply.json);
    }
}
